const std = @import("std");
const math = std.math;
const d_model: usize = 18432;
const grid_size: usize = 5;

pub const NeuralState = struct {
    potential: f64,
    quantum_phase: f64,
    lorenz_params: [3]f64,
    spline_coeffs: [d_model][grid_size]f64,
};

pub fn update_state(state: *NeuralState, token_embedding: []f64, grid_val: usize) void {
    var sum_emb: f64 = 0.0;
    for (token_embedding) |emb| {
        sum_emb += emb;
    }
    if (grid_val > 0) {
        const d_model_float: f64 = @floatFromInt(d_model);
        const grid_float: f64 = @floatFromInt(grid_val);
        const product: f64 = d_model_float * grid_float;
        if (product > 0.0) {
            const log_val: f64 = @log(product);
            state.potential += sum_emb * 0.01 * log_val;
        }
    }
    state.quantum_phase += math.pi / 180.0;
}

fn b_spline_basis_cox_de_boor(x: f64, knots: []const f64, i: usize, p: u32, allocator: std.mem.Allocator) !f64 {
    if (p == 0) {
        if (i + 1 >= knots.len) {
            return 0.0;
        }
        if (i == knots.len - 2) {
            if (x >= knots[i] and x <= knots[i + 1]) {
                return 1.0;
            } else {
                return 0.0;
            }
        } else {
            if (x >= knots[i] and x < knots[i + 1]) {
                return 1.0;
            } else {
                return 0.0;
            }
        }
    } else {
        const p_usize: usize = @intCast(p);
        var left_term: f64 = 0.0;
        var right_term: f64 = 0.0;

        if (i + p_usize < knots.len) {
            const denom_left = knots[i + p_usize] - knots[i];
            if (denom_left != 0.0) {
                const basis_left = try b_spline_basis_cox_de_boor(x, knots, i, p - 1, allocator);
                left_term = ((x - knots[i]) / denom_left) * basis_left;
            }
        }

        if (i + 1 < knots.len and i + p_usize + 1 < knots.len) {
            const denom_right = knots[i + p_usize + 1] - knots[i + 1];
            if (denom_right != 0.0) {
                const basis_right = try b_spline_basis_cox_de_boor(x, knots, i + 1, p - 1, allocator);
                right_term = ((knots[i + p_usize + 1] - x) / denom_right) * basis_right;
            }
        }

        return left_term + right_term;
    }
}

pub fn kan_spline_eval(x: f64, coeffs: [grid_size]f64, g: usize, allocator: std.mem.Allocator) !f64 {
    if (g == 0) {
        return 0.0;
    }

    const degree: u32 = 3;
    const degree_usize: usize = @intCast(degree);
    const num_control_points = grid_size;
    const num_knots = num_control_points + degree_usize + 1;

    var knots = try allocator.alloc(f64, num_knots);
    defer allocator.free(knots);

    for (0..num_knots) |i| {
        if (i <= degree_usize) {
            knots[i] = 0.0;
        } else if (i >= num_control_points) {
            knots[i] = 1.0;
        } else {
            const interior_index = i - degree_usize;
            const num_interior = num_control_points - degree_usize;
            const idx_float: f64 = @floatFromInt(interior_index);
            const num_float: f64 = @floatFromInt(num_interior);
            knots[i] = idx_float / num_float;
        }
    }

    var clamped_x = x;
    if (clamped_x < 0.0) {
        clamped_x = 0.0;
    }
    if (clamped_x > 1.0) {
        clamped_x = 1.0;
    }

    var sum: f64 = 0.0;
    for (0..num_control_points) |i| {
        const basis_val = try b_spline_basis_cox_de_boor(clamped_x, knots, i, degree, allocator);
        sum += basis_val * coeffs[i];
    }

    return sum;
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var state: NeuralState = undefined;
    state.potential = 0.0;
    state.quantum_phase = 0.0;
    state.lorenz_params[0] = 10.0;
    state.lorenz_params[1] = 28.0;
    state.lorenz_params[2] = 8.0 / 3.0;

    for (0..d_model) |i| {
        for (0..grid_size) |j| {
            state.spline_coeffs[i][j] = 0.0;
        }
    }

    var token_emb: [d_model]f64 = undefined;
    for (0..d_model) |i| {
        token_emb[i] = 0.0;
    }

    update_state(&state, token_emb[0..], grid_size);

    const spline_result = try kan_spline_eval(0.5, state.spline_coeffs[0], grid_size, allocator);

    const stdout = std.io.getStdOut().writer();
    try stdout.print("Quantum Zig Loaded for JAIDE V33\n", .{});
    try stdout.print("Spline evaluation result: {d}\n", .{spline_result});
}
