fn b_spline_basis_iter(x: f64, knots: []const f64, degree: usize, basis_out: []f64) void {
    const n = knots.len - 1;
    if (degree + 1 > knots.len or basis_out.len < n - degree) {
        return;
    }

    var temp_basis = std.mem.zeroes([2 * (knots.len + 1)]f64);
    var current_level: []f64 = &temp_basis[0..knots.len];
    var next_level: []f64 = &temp_basis[knots.len..];

    for (0..n) |i| {
        if (x >= knots[i] and x < knots[i + 1]) {
            current_level[i] = 1.0;
        } else {
            current_level[i] = 0.0;
        }
    }
    if (x == knots[n]) {
        current_level[n - 1] = 1.0;
    }

    var p: usize = 1;
    while (p <= degree) : (p += 1) {
        for (0..n - p) |i| {
            var term1: f64 = 0.0;
            const num1 = x - knots[i];
            const den1 = knots[i + p] - knots[i];
            if (den1 != 0.0) {
                term1 = num1 / den1 * current_level[i];
            }

            var term2: f64 = 0.0;
            const num2 = knots[i + p + 1] - x;
            const den2 = knots[i + p + 1] - knots[i + 1];
            if (den2 != 0.0) {
                term2 = num2 / den2 * current_level[i + 1];
            }
            next_level[i] = term1 + term2;
        }
        const swap_tmp = current_level;
        current_level = next_level;
        next_level = swap_tmp;
    }

    for (0..n - degree) |i| {
        if (i < basis_out.len) {
            basis_out[i] = current_level[i];
        }
    }
}

